            seed_sql: mod6Seed,
            expected_query: "SELECT a.member_name FROM project_a a WHERE EXISTS (SELECT 1 FROM project_b b WHERE b.member_name = a.member_name);",
            starterQuery: "SELECT * FROM project_a;",
