export function resolveQuestionForEngine(q: Question, engine: string): Question {
    const override = engine === 'mysql' ? q.engineOverrides?.mysql : q.engineOverrides?.postgres;
    if (!override) return q;
    return {
        ...q,
        ...override,
        title: override.title ?? q.title,
        conceptExplanation: override.conceptExplanation ?? q.conceptExplanation,
        syntaxPatterns: override.syntaxPatterns ?? q.syntaxPatterns,
        instructions: override.instructions ?? q.instructions,
        seed_sql: override.seed_sql ?? q.seed_sql,
        expected_query: override.expected_query ?? q.expected_query,
        starterQuery: override.starterQuery ?? q.starterQuery,
        table_names: override.table_names ?? q.table_names,
        targetSchemaBlueprint: override.targetSchemaBlueprint ?? q.targetSchemaBlueprint,
        mockPreviewData: override.mockPreviewData ?? q.mockPreviewData,
        previewData: override.previewData ?? q.previewData,
        verification_query: override.verification_query ?? q.verification_query
    };
}
